WITH address_returns AS ( SELECT ca.ca_city, ca.ca_state, ca.ca_location_type, sr.sr_net_loss, sr.sr_return_amt, sr.sr_return_quantity, hd.hd_vehicle_count, i.i_brand FROM store_returns sr JOIN customer_address ca ON sr.sr_addr_sk = ca.ca_address_sk JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk ), city_agg AS ( SELECT ca_city, ca_state, ca_location_type, SUM(sr_net_loss) AS total_net_loss, SUM(sr_return_amt) AS total_return_amt, SUM(sr_return_quantity) AS total_qty, COUNT(*) AS cnt_returns, AVG(hd_vehicle_count) AS avg_vehicle_count, COUNT(DISTINCT i_brand) AS distinct_brands FROM address_returns GROUP BY ca_city, ca_state, ca_location_type ) SELECT ca_city, ca_state, ca_location_type, total_net_loss, total_return_amt, total_qty, cnt_returns, avg_vehicle_count, distinct_brands, CASE WHEN total_net_loss > 20000 THEN 'Critical' WHEN total_net_loss BETWEEN 10000 AND 20000 THEN 'High' WHEN total_net_loss BETWEEN 5000 AND 10000 THEN 'Medium' ELSE 'Low' END AS loss_severity, SUM(total_net_loss) OVER (ORDER BY total_net_loss DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_loss, RANK() OVER (ORDER BY total_net_loss DESC) AS net_loss_rank FROM city_agg WHERE cnt_returns >= 5 ORDER BY total_net_loss DESC LIMIT 20
